package main

import "strings"

func triageDescription() string {
	return "\u9762\u5411\u60a3\u8005\u7684\u667a\u80fd\u5bfc\u8bca\u52a9\u624b"
}

func triageInstruction() string {
	return strings.Join([]string{
		"\u4f60\u662f\u4e00\u540d\u4e25\u8c28\u3001\u81ea\u7136\u3001\u6709\u4e0a\u4e0b\u6587\u8bb0\u5fc6\u7684\u4e2d\u6587\u667a\u80fd\u5bfc\u8bca\u52a9\u624b\u3002\u4f60\u5e2e\u52a9\u7528\u6237\u68b3\u7406\u75c7\u72b6\u3001\u5224\u65ad\u7d27\u6025\u7a0b\u5ea6\u5e76\u5efa\u8bae\u5c31\u533b\u65b9\u5411\uff0c\u4e0d\u505a\u786e\u8bca\uff0c\u4e5f\u4e0d\u66ff\u4ee3\u533b\u751f\u3002",
		"1. \u5fc5\u987b\u627f\u63a5\u540c\u4e00\u4f1a\u8bdd\u7684\u5386\u53f2\uff0c\u77ed\u53e5\u8ffd\u95ee\u4e0d\u5f97\u8ba9\u7528\u6237\u4ece\u5934\u91cd\u590d\u3002",
		"2. \u5148\u76f4\u63a5\u56de\u7b54\u5f53\u524d\u95ee\u9898\uff0c\u518d\u51b3\u5b9a\u662f\u5426\u8ffd\u95ee\uff1b\u4e00\u6b21\u95ee\u591a\u4e2a\u95ee\u9898\u65f6\u5fc5\u987b\u5206\u522b\u56de\u7b54\u3002",
		"3. \u9ed8\u8ba4 100-180 \u4e2a\u6c49\u5b57\u30012-3 \u4e2a\u77ed\u6bb5\u843d\u6216\u8981\u70b9\uff0c\u4e0d\u8f93\u51fa\u767e\u79d1\u5f0f\u957f\u6e05\u5355\u3002",
		"4. \u6bcf\u8f6e\u6700\u591a\u8ffd\u95ee 1 \u4e2a\u6700\u5173\u952e\u95ee\u9898\uff0c\u5df2\u7ecf\u56de\u7b54\u7684\u4fe1\u606f\u4e0d\u8981\u518d\u95ee\u3002",
		"5. \u7528\u836f\u4fe1\u606f\u4e0d\u8db3\u65f6\u4e0d\u7f57\u5217\u836f\u540d\uff0c\u4e0d\u5f00\u5904\u65b9\uff0c\u4e0d\u63a8\u8350\u6297\u751f\u7d20\uff1b\u53ef\u8bf4\u660e\u975e\u5904\u65b9\u836f\u7c7b\u522b\u548c\u54a8\u8be2\u836f\u5e08\u7684\u8fb9\u754c\u3002",
		"6. \u513f\u7ae5\u3001\u5b55\u5987\u3001\u8001\u4eba\u3001\u6162\u6027\u75c5\u3001\u8fc7\u654f\u53f2\u6216\u5408\u5e76\u7528\u836f\u8005\u4e0d\u7ed9\u5177\u4f53\u5242\u91cf\u3002",
		"7. \u51fa\u73b0\u80f8\u75db\u3001\u660e\u663e\u547c\u5438\u56f0\u96be\u3001\u610f\u8bc6\u5f02\u5e38\u3001\u5355\u4fa7\u80a2\u4f53\u65e0\u529b\u3001\u6301\u7eed\u9ad8\u70ed\u4f34\u7cbe\u795e\u5dee\u3001\u5927\u51fa\u8840\u7b49\u5371\u9669\u4fe1\u53f7\u65f6\uff0c\u660e\u786e\u5efa\u8bae\u7acb\u5373\u6025\u8bca\u6216\u62e8\u6253\u6025\u6551\u7535\u8bdd\u3002",
		"8. \u8bed\u8a00\u50cf\u8010\u5fc3\u7684\u771f\u4eba\u5bfc\u8bca\u62a4\u58eb\uff1a\u76f4\u63a5\u3001\u7b80\u6d01\u3001\u5177\u4f53\uff0c\u4e0d\u8bf4\u4f5c\u4e3a AI\uff0c\u4e0d\u6dfb\u52a0\u65e5\u671f\u6216\u65f6\u95f4\u6233\u3002",
	}, "\n")
}

func fallbackTriageReply(message string) string {
	value := strings.TrimSpace(message)
	switch {
	case containsAny(value, "\u80f8\u75db", "\u547c\u5438\u56f0\u96be", "\u5598\u4e0d\u4e0a\u6c14", "\u660f\u8ff7", "\u610f\u8bc6\u4e0d\u6e05", "\u5927\u51fa\u8840"):
		return "\u8fd9\u4e9b\u60c5\u51b5\u9700\u8981\u4f18\u5148\u6392\u9664\u6025\u75c7\u3002\u8bf7\u7acb\u5373\u505c\u6b62\u6d3b\u52a8\uff0c\u5c31\u5730\u4f11\u606f\uff1b\u5982\u75c7\u72b6\u6301\u7eed\u3001\u52a0\u91cd\uff0c\u6216\u4f34\u51fa\u6c57\u3001\u5934\u6655\u3001\u53e3\u5507\u53d1\u7d2b\uff0c\u8bf7\u7acb\u5373\u62e8\u6253 120\uff0c\u4e0d\u8981\u81ea\u884c\u5f00\u8f66\u3002"
	case containsAny(value, "\u7761\u5f97\u665a", "\u71ac\u591c", "\u5931\u7720", "\u7761\u4e0d\u597d"):
		return "\u665a\u7761\u548c\u7761\u7720\u4e0d\u8db3\u786e\u5b9e\u53ef\u80fd\u52a0\u91cd\u5934\u75db\u3001\u5934\u6655\u548c\u75b2\u52b3\u3002\u4eca\u5929\u53ef\u5148\u8865\u6c34\u3001\u907f\u514d\u7a7a\u8179\u548c\u957f\u65f6\u95f4\u770b\u5c4f\u5e55\uff0c\u5c3d\u91cf\u63d0\u524d\u4f11\u606f\u3002\u5982\u5934\u75db\u7a81\u7136\u5267\u70c8\uff0c\u6216\u4f34\u610f\u8bc6\u5f02\u5e38\u3001\u80a2\u4f53\u65e0\u529b\u3001\u53cd\u590d\u5455\u5410\uff0c\u9700\u53ca\u65f6\u6025\u8bca\u3002\u4f60\u6628\u665a\u5927\u7ea6\u7761\u4e86\u51e0\u4e2a\u5c0f\u65f6\uff1f"
	case containsAny(value, "\u809a\u5b50\u75bc", "\u809a\u5b50\u75db", "\u8179\u75db", "\u80c3\u75bc", "\u80c3\u75db"):
		if containsAny(value, "\u6b62\u75bc\u836f", "\u6b62\u75db\u836f", "\u6b62\u75bc\u7247", "\u6b62\u75db\u7247") {
			return "\u8179\u75db\u65f6\u4e0d\u5efa\u8bae\u53cd\u590d\u9760\u6b62\u75db\u836f\u538b\u4f4f\u75c7\u72b6\uff0c\u56e0\u4e3a\u53ef\u80fd\u63a9\u76d6\u9611\u5c3e\u708e\u3001\u80c3\u80a0\u708e\u6216\u5176\u4ed6\u9700\u8981\u53ca\u65f6\u5904\u7406\u7684\u95ee\u9898\u3002\u5148\u6682\u505c\u81ea\u884c\u52a0\u836f\uff0c\u6ce8\u610f\u836f\u540d\u548c\u5df2\u670d\u5242\u91cf\uff0c\u5c11\u91cf\u996e\u6c34\uff0c\u6682\u907f\u514d\u996e\u9152\u548c\u523a\u6fc0\u6027\u98df\u7269\u3002\u5982\u75bc\u75db\u6301\u7eed\u52a0\u91cd\u3001\u53f3\u4e0b\u8179\u56fa\u5b9a\u75db\u3001\u53cd\u590d\u5455\u5410\u3001\u9ed1\u4fbf/\u4fbf\u8840\u3001\u53d1\u70ed\u6216\u8179\u90e8\u53d1\u786c\uff0c\u8bf7\u5c3d\u5feb\u6025\u8bca\u3002\u4f60\u5403\u7684\u6b62\u75db\u836f\u53eb\u4ec0\u4e48\uff0c\u75bc\u75db\u4e3b\u8981\u5728\u8179\u90e8\u54ea\u4e2a\u4f4d\u7f6e\uff1f"
		}
		return "\u8179\u75db\u9700\u8981\u7ed3\u5408\u4f4d\u7f6e\u3001\u6301\u7eed\u65f6\u95f4\u548c\u4f34\u968f\u75c7\u72b6\u5224\u65ad\u3002\u5148\u4f11\u606f\u3001\u5c11\u91cf\u996e\u6c34\uff0c\u6682\u907f\u514d\u996e\u9152\u3001\u8f9b\u8fa3\u98df\u7269\u548c\u81ea\u884c\u53e0\u52a0\u7528\u836f\u3002\u5982\u75bc\u75db\u5267\u70c8\u6216\u6301\u7eed\u52a0\u91cd\uff0c\u4f34\u53cd\u590d\u5455\u5410\u3001\u53d1\u70ed\u3001\u4fbf\u8840/\u9ed1\u4fbf\u6216\u8179\u90e8\u53d1\u786c\uff0c\u8bf7\u53ca\u65f6\u6025\u8bca\u3002\u75bc\u75db\u4e3b\u8981\u5728\u4e0a\u8179\u3001\u809a\u8110\u5468\u56f4\uff0c\u8fd8\u662f\u53f3\u4e0b\u8179\uff1f"
	case containsAny(value, "\u5934\u75db", "\u5934\u6655"):
		return "\u5934\u75db\u5934\u6655\u53ef\u5148\u5750\u4e0b\u6216\u5e73\u8eba\u4f11\u606f\uff0c\u8865\u6c34\uff0c\u6682\u65f6\u907f\u514d\u5f00\u8f66\u548c\u9ad8\u5904\u4f5c\u4e1a\u3002\u5982\u6709\u7a81\u7136\u5267\u70c8\u5934\u75db\u3001\u8bf4\u8bdd\u4e0d\u6e05\u3001\u80a2\u4f53\u65e0\u529b\u3001\u610f\u8bc6\u5f02\u5e38\u6216\u53cd\u590d\u5455\u5410\uff0c\u8bf7\u7acb\u5373\u6025\u8bca\u3002\u8bf7\u95ee\u75c7\u72b6\u662f\u7a81\u7136\u51fa\u73b0\uff0c\u8fd8\u662f\u9010\u6e10\u52a0\u91cd\uff1f"
	default:
		return "\u6211\u5df2\u8bb0\u4e0b\u4f60\u8865\u5145\u7684\u4fe1\u606f\u3002\u76ee\u524d\u53ef\u5148\u4f11\u606f\u3001\u8865\u6c34\u5e76\u89c2\u5bdf\u75c7\u72b6\u53d8\u5316\uff1b\u5982\u51fa\u73b0\u660e\u663e\u52a0\u91cd\u6216\u80f8\u75db\u3001\u547c\u5438\u56f0\u96be\u3001\u610f\u8bc6\u5f02\u5e38\u7b49\u5371\u9669\u4fe1\u53f7\uff0c\u8bf7\u53ca\u65f6\u6025\u8bca\u3002"
	}
}
